def transform(grid):
    from collections import Counter

    # Find separator rows (rows with uniform color)
    row_sep = []
    for r in range(len(grid)):
        row_colors = list(set(grid[r]))
        if len(row_colors) == 1:
            row_sep.append(r)

    if not row_sep:
        return [[0] * len(grid[0]) for _ in range(len(grid))]

    # Find separator columns (columns with uniform separator color)
    sep_color = grid[row_sep[0]][0]
    col_sep = []
    for c in range(len(grid[0])):
        if all(grid[r][c] == sep_color for r in range(len(grid))):
            col_sep.append(c)

    if not col_sep:
        return [[0] * len(grid[0]) for _ in range(len(grid))]

    # Get background and object colors
    cell_counts = Counter()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            cell_counts[grid[r][c]] += 1

    bg_color = max(cell_counts, key=cell_counts.get)
    others = [c for c in cell_counts if c != bg_color and c != sep_color]
    obj_color = others[0] if others else None

    if obj_color is None:
        return [[bg_color for _ in range(len(grid[0]))] for _ in range(len(grid))]

    # Calculate region boundaries
    row_ranges = []
    start = 0
    for rs in row_sep:
        row_ranges.append([start, rs])
        start = rs + 1
    row_ranges.append([start, len(grid)])

    col_ranges = []
    start = 0
    for cs in col_sep:
        col_ranges.append([start, cs])
        start = cs + 1
    col_ranges.append([start, len(grid[0])])

    # Build output grid
    rows_out = len(row_ranges)
    cols_out = len(col_ranges)
    output = []

    for r_idx in range(rows_out):
        output_row = []
        r_start, r_end = row_ranges[r_idx]
        for c_idx in range(cols_out):
            c_start, c_end = col_ranges[c_idx]
            # Count objects in this region
            obj_count = 0
            for r in range(r_start, r_end):
                for c in range(c_start, c_end):
                    if grid[r][c] == obj_color:
                        obj_count += 1

            # Rule: 1 object -> bg_color, 2+ objects -> 1
            if obj_count == 1:
                output_row.append(bg_color)
            else:
                output_row.append(1)
        output.append(output_row)

    return output
